1	package zkcircuit
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"os"
10		"path/filepath"
11		"sort"
12		"strconv"
13		"strings"
14		"sync"
15	)
16	
17	// on-disk layout inside the data directory:
18	//
19	//	data.json    – the committed state (JSON envelope, atomically replaced)
20	//	data.json.tmp– staging file for the next commit (rename(2) target)
21	//	lock         – flock file serializing concurrent processes
22	//
23	// The envelope carries an explicit format version: files written by an
24	// incompatible future build are refused rather than silently migrated or
25	// overwritten.
26	const (
27		dirDataFile = "data.json"
28		dirTmpFile  = "data.json.tmp"
29		dirLockFile = "lock"
30	
31		// FormatVersion is the on-disk format this build writes and accepts.
32		FormatVersion = 1
33	)
34	
35	// envelope is the persisted state container.
36	//
37	// Circuits are kept as raw JSON during decoding so persistCircuit's strict
38	// UnmarshalJSON — rather than encoding/json's silent zero-value filling —
39	// decides what a committed circuit record may look like. UnmarshalJSON first
40	// walks the token stream (scanEnvelopeDuplicates) and rejects a repeated
41	// object key anywhere encoding/json would otherwise keep the last value. At
42	// the envelope's top level that comparison is case-insensitive for the five
43	// known fields (format/circuits/setups/jobs/artifacts): a second spelling
44	// that differs only in ASCII letter case — including one JSON-escaped — names
45	// the same field and corrupts the read instead of overriding it. A spelling
46	// that Unicode case-folds onto one of those fields yet is not an ASCII case
47	// variant ("circuitſ" with U+017F long s, directly written or ſ-escaped)
48	// is likewise corruption even when it is the only spelling present, since
49	// encoding/json's own tag matching would fill the field from it; a later
50	// "circuitſ": [] must never read the circuits as empty and drop them on the
51	// next commit.
52	type envelope struct {
53		Format    int               `json:"format"`
54		Circuits  []persistCircuit  `json:"circuits"`
55		Setups    []persistSetup    `json:"setups"`
56		Jobs      []persistJob      `json:"jobs"`
57		Artifacts []persistArtifact `json:"artifacts,omitempty"`
58	}
59	
60	// envelopeWire is the decoding-only shape: circuit records arrive raw so
61	// their own strict decoder can require every field explicitly.
62	type envelopeWire struct {
63		Format    int               `json:"format"`
64		Circuits  []json.RawMessage `json:"circuits"`
65		Setups    []persistSetup    `json:"setups"`
66		Jobs      []persistJob      `json:"jobs"`
67		Artifacts []persistArtifact `json:"artifacts,omitempty"`
68	}
69	
70	func (e *envelope) UnmarshalJSON(raw []byte) error {
71		// Reject repeated keys before decoding: encoding/json silently keeps the
72		// last value of a duplicate. The walk is layered so a repeated field is
73		// attributed to the record it belongs to (a duplicate "frozen" inside
74		// circuit #3, not a generic envelope complaint).
75		if err := scanEnvelopeDuplicates(raw); err != nil {
76			return err
77		}
78		var wire envelopeWire
79		if err := json.Unmarshal(raw, &wire); err != nil {
80			var se StoreError
81			if errors.As(err, &se) && se.Kind == ErrDataCorrupt.Kind {
82				return err // an inner record decoder already named the problem
83			}
84			return corruptf("data file envelope is not valid JSON: %v", err)
85		}
86		e.Format = wire.Format
87		e.Setups = wire.Setups
88		e.Jobs = wire.Jobs
89		e.Artifacts = wire.Artifacts
90		if wire.Circuits == nil {
91			e.Circuits = nil
92		} else {
93			e.Circuits = make([]persistCircuit, len(wire.Circuits))
94		}
95		for i, craw := range wire.Circuits {
96			var record persistCircuit
97			if err := json.Unmarshal(craw, &record); err != nil {
98				var se StoreError
99				if errors.As(err, &se) {
100					// Re-tag as one corruption error carrying the record index,
101					// so the detail survives errors.As unwrapping in loadLocked.
102					return StoreError{Kind: ErrDataCorrupt.Kind,
103						Detail: fmt.Sprintf("circuit record #%d: %s", i+1, se.Detail)}
104				}
105				return corruptf("circuit record #%d: %v", i+1, err)
106			}
107			e.Circuits[i] = record
108		}
109		return nil
110	}
111	
112	// envelopeTopFields are the five fields an envelope may carry. Their
113	// canonical (standard lowercase) spellings are the wire tags on envelope and
114	// envelopeWire; JSON keys are tokenized after unescaping.
115	var envelopeTopFields = []string{"format", "circuits", "setups", "jobs", "artifacts"}
116	
117	// canonicalEnvelopeField reports the standard lowercase name of one of the
118	// five envelope fields when key names it under any ASCII letter-case spelling
119	// ("format", "FORMAT", "FoRmAt", …). Keys are already JSON-unescaped by the
120	// tokenizer, so an escaped spelling of any such form lands here too. A
121	// non-canonical key (different length or a mismatching byte, including
122	// non-ASCII lookalikes and unknown fields such as "CIRCUIT") returns "".
123	func canonicalEnvelopeField(key string) string {
124		for _, field := range envelopeTopFields {
125			if len(key) != len(field) {
126				continue
127			}
128			i := 0
129			for i < len(key) {
130				c := key[i]
131				if c >= 'A' && c <= 'Z' {
132					c += 'a' - 'A'
133				}
134				if c != field[i] {
135					break
136				}
137				i++
138			}
139			if i == len(field) {
140				return field
141			}
142		}
143		return ""
144	}
145	
146	// envelopeFieldLookalike reports the standard lowercase name of one of the
147	// five envelope fields when key names it under a spelling encoding/json's
148	// struct-tag matching would fold onto the field but which is not an accepted
149	// ASCII letter-case spelling (canonicalEnvelopeField reports those). Tag
150	// matching folds with the Unicode simple case-folding rules
151	// (strings.EqualFold), so "circuitſ" (U+017F long s, written directly or as
152	// the JSON escape u017f — keys arrive here already unescaped) names the
153	// circuits field exactly like "circuits", even standing alone. Such a
154	// lookalike is damage whatever its value: a later "circuitſ": [] would
155	// otherwise override a populated circuits array through last-value-wins and
156	// the records would vanish on the next commit. A key that does not fold onto
157	// any known field — an unrelated unknown name such as "note", or "cİrcuits"
158	// with U+0130 dotted capital I, which does not fold — returns "" and keeps
159	// the ordinary unknown-member handling.
160	func envelopeFieldLookalike(key string) string {
161		if canonicalEnvelopeField(key) != "" {
162			return "" // an accepted ASCII spelling, not a lookalike
163		}
164		for _, field := range envelopeTopFields {
165			if strings.EqualFold(key, field) {
166				return field
167			}
168		}
169		return ""
170	}
171	
172	// scanEnvelopeDuplicates tokenizes the committed envelope and rejects every
173	// repeated object key. The five known top-level fields are identified case-
174	// insensitively: two spellings that differ only in ASCII letter case (both
175	// keys already JSON-unescaped at this point) are the same field, in whatever
176	// order they appear and whether or not their values agree, so a later
177	// "CIRCUITS" or "FORMAT" can never override an earlier one through encoding/
178	// json's last-value-wins struct matching. Such a pair is reported as a
179	// duplicated top-level field named by its standard lowercase spelling.
180	//
181	// A non-ASCII spelling that folds onto a known field but is not an ASCII case
182	// variant ("circuitſ", "setupſ", "jobſ", "artifactſ" with U+017F long s,
183	// directly written or ſ-escaped) is rejected outright as data corruption:
184	// encoding/json would match it onto the field, so ignoring it as unknown
185	// could let its value replace the real one (an empty array hiding every
186	// record), and accepting it would let the records vanish on the next commit.
187	// The rule holds for the lookalike appearing alone — value a legal record, an
188	// empty array or null alike — and for it appearing beside the canonical
189	// spelling or an ASCII case variant, in either order and whether the values
190	// agree. The error names both the standard field and the actual spelling.
191	//
192	// Circuit records are scanned one level deep only — their top-level fields
193	// are checked here (with the record's 1-based index reported), while values
194	// such as the constraint definition are skipped and left to their own strict
195	// decoders. Every other envelope member is scanned recursively so a
196	// duplicated key anywhere in committed data fails the read instead of
197	// silently resolving to its last value.
198	func scanEnvelopeDuplicates(raw []byte) error {
199		dec := json.NewDecoder(bytes.NewReader(bytes.TrimSpace(raw)))
200		dec.UseNumber()
201		open, err := dec.Token()
202		if err != nil || open != json.Delim('{') {
203			return corruptf("data file envelope must be a JSON object")
204		}
205		// Exact spellings retain the pre-existing check for unknown keys;
206		// canonical names remember a known field's first occurrence regardless
207		// of the case it was written in.
208		seenTop := make(map[string]bool)
209		seenCanonical := make(map[string]bool)
210		for dec.More() {
211			keyTok, err := dec.Token()
212			if err != nil {
213				return corruptf("data file envelope is not valid JSON: %v", err)
214			}
215			key, ok := keyTok.(string)
216			if !ok {
217				return corruptf("data file envelope is not valid JSON")
218			}
219			// Reject a non-ASCII spelling that encoding/json's Unicode-folded tag
220			// matching would read as a known field ("circuitſ" with long s,
221			// directly written or ſ-escaped) before anything else. It is damage
222			// even on its own and whatever its value — a legal record, an empty
223			// array or null — and whether it precedes or follows the canonical or
224			// an ASCII case-variant spelling: the read may neither ignore it as an
225			// unknown member nor choose one of the values and carry on.
226			if canonical := envelopeFieldLookalike(key); canonical != "" {
227				return corruptf("data file envelope carries top-level field %q under non-ASCII spelling %q; such a lookalike spelling is data corruption",
228					canonical, key)
229			}
230			if canonical := canonicalEnvelopeField(key); canonical != "" {
231				if seenCanonical[canonical] {
232					if key == canonical {
233						return corruptf("data file envelope contains duplicate top-level field %q", canonical)
234					}
235					return corruptf("data file envelope contains duplicate top-level field %q (also present as %q)",
236						canonical, key)
237				}
238				seenCanonical[canonical] = true
239				if canonical == "circuits" {
240					if err := scanCircuitArrayDuplicates(dec); err != nil {
241						return err
242					}
243					continue
244				}
245				if err := skipValueWithDupKeys(dec, "data file envelope field "+strconv.Quote(canonical)); err != nil {
246					return err
247				}
248				continue
249			}
250			if seenTop[key] {
251				return corruptf("data file envelope contains duplicate field %q", key)
252			}
253			seenTop[key] = true
254			if err := skipValueWithDupKeys(dec, "data file envelope field "+strconv.Quote(key)); err != nil {
255				return err
256			}
257		}
258		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
259			return corruptf("data file envelope is not valid JSON")
260		}
261		if _, err := dec.Token(); err != io.EOF {
262			return corruptf("data file envelope is not valid JSON: trailing data after the object")
263		}
264		return nil
265	}
266	
267	// scanCircuitArrayDuplicates consumes one "circuits" value positioned at its
268	// opening bracket and checks only each record's own top-level keys. The
269	// enclosing key may carry any case spelling, but the field it names is the
270	// canonical "circuits". A null array stays the pre-existing "no records"
271	// reading.
272	func scanCircuitArrayDuplicates(dec *json.Decoder) error {
273		tok, err := dec.Token()
274		if err != nil {
275			return corruptf("data file envelope field \"circuits\" is not valid JSON: %v", err)
276		}
277		if tok == nil { // null: json.Unmarshal would produce no records
278			return nil
279		}
280		if tok != json.Delim('[') {
281			return corruptf("data file envelope field \"circuits\" must be an array")
282		}
283		index := 0
284		for dec.More() {
285			index++
286			what := fmt.Sprintf("circuit record #%d", index)
287			open, err := dec.Token()
288			if err != nil {
289				return corruptf("%s is not valid JSON: %v", what, err)
290			}
291			if open == nil {
292				return corruptf("%s must be a JSON object, not null", what)
293			}
294			if open != json.Delim('{') {
295				return corruptf("%s must be a JSON object", what)
296			}
297			seen := make(map[string]bool)
298			for dec.More() {
299				keyTok, err := dec.Token()
300				if err != nil {
301					return corruptf("%s is not valid JSON: %v", what, err)
302				}
303				key, ok := keyTok.(string)
304				if !ok {
305					return corruptf("%s is not valid JSON", what)
306				}
307				if seen[key] {
308					return corruptf("%s contains duplicate field %q", what, key)
309				}
310				seen[key] = true
311				// Skip the whole value without descending: nested objects
312				// (definition) own their own strict duplicate checks.
313				var skip json.RawMessage
314				if err := dec.Decode(&skip); err != nil {
315					return corruptf("%s is not valid JSON: %v", what, err)
316				}
317			}
318			if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
319				return corruptf("%s is not valid JSON", what)
320			}
321		}
322		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim(']') {
323			return corruptf("data file envelope field \"circuits\" is not valid JSON")
324		}
325		return nil
326	}
327	
328	// skipValueWithDupKeys consumes one JSON value positioned at its first token,
329	// recursively rejecting duplicate object keys.
330	func skipValueWithDupKeys(dec *json.Decoder, what string) error {
331		tok, err := dec.Token()
332		if err != nil {
333			return corruptf("%s is not valid JSON: %v", what, err)
334		}
335		delim, ok := tok.(json.Delim)
336		if !ok {
337			return nil // scalar (including null)
338		}
339		switch delim {
340		case '{':
341			seen := make(map[string]bool)
342			for dec.More() {
343				keyTok, err := dec.Token()
344				if err != nil {
345					return corruptf("%s is not valid JSON: %v", what, err)
346				}
347				key, ok := keyTok.(string)
348				if !ok {
349					return corruptf("%s is not valid JSON", what)
350				}
351				if seen[key] {
352					return corruptf("%s contains duplicate field %q", what, key)
353				}
354				seen[key] = true
355				if err := skipValueWithDupKeys(dec, what+" "+strconv.Quote(key)); err != nil {
356					return err
357				}
358			}
359			if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
360				return corruptf("%s is not valid JSON", what)
361			}
362		case '[':
363			index := 0
364			for dec.More() {
365				index++
366				if err := skipValueWithDupKeys(dec, fmt.Sprintf("%s element #%d", what, index)); err != nil {
367					return err
368				}
369			}
370			if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim(']') {
371				return corruptf("%s is not valid JSON", what)
372			}
373		}
374		return nil
375	}
376	
377	type persistTerm struct {
378		Wire  int    `json:"wire"`
379		Coeff string `json:"coeff"`
380	}
381	
382	type persistConstraint struct {
383		A []persistTerm `json:"a"`
384		B []persistTerm `json:"b"`
385		C []persistTerm `json:"c"`
386	}
387	
388	// persistDefinition is the canonical, already-validated constraint set bound
389	// to one circuit version. The public/private partition is owned by the
390	// circuit record and is deliberately not duplicated here, so it can never
391	// drift from the declared counts.
392	type persistDefinition struct {
393		Modulus     string              `json:"modulus"`
394		Constraints []persistConstraint `json:"constraints"`
395	}
396	
397	// persistArtifact is a compiled artifact: the version's identity and
398	// constraint count bound to its recomputable SHA-256 hash.
399	type persistArtifact struct {
400		Name        string `json:"name"`
401		Version     int    `json:"version"`
402		Modulus     int64  `json:"modulus"`
403		Constraints int    `json:"constraints"`
404		Hash        string `json:"hash"`
405	}
406	
407	type persistCircuit struct {
408		Name          string             `json:"name"`
409		Version       int                `json:"version"`
410		Constraints   int                `json:"constraints"`
411		PublicInputs  int                `json:"public_inputs"`
412		PrivateInputs int                `json:"private_inputs"`
413		Frozen        bool               `json:"frozen"`
414		Description   string             `json:"description"`
415		Definition    *persistDefinition `json:"definition,omitempty"`
416	}
417	
418	// Strict decoding of committed circuit records.
419	//
420	// A circuit record in data.json must name each of name, version, constraints,
421	// public_inputs, private_inputs, frozen and description exactly once, with
422	// the exact JSON type the writer emits (string / integer / integer / integer
423	// / integer / boolean / string). A missing key, a null, a wrong type or a
424	// repeated key is data corruption and refuses the whole directory read: a
425	// missing or null frozen flag must not silently read as false (turning a
426	// frozen version back into an editable draft), and a repeated key must not
427	// resolve to its last value. An explicit 0, false or "" is an ordinary value
428	// and stays legal. The definition member remains the one optional field: it
429	// may be absent or null (the legacy counts-only state); when present it goes
430	// through the strict persistDefinition decoder.
431	//
432	// Only shape is judged here. The domain rules (non-blank name, positive
433	// version and constraint count, non-negative input counts) keep being
434	// re-checked by validateEnvelope.
435	
436	var persistCircuitFields = []string{
437		"name", "version", "constraints", "public_inputs", "private_inputs",
438		"frozen", "description", "definition",
439	}
440	
441	// storedRecordShape is the shared strict-JSON rule set (definition_schema.go)
442	// tagged for committed data: every structural failure in a stored circuit
443	// record is data corruption, never a bad request.
444	var storedRecordShape = jsonShape{fail: corruptf}
445	
446	func (c *persistCircuit) UnmarshalJSON(raw []byte) error {
447		const what = "stored circuit record"
448		if string(bytes.TrimSpace(raw)) == "null" {
449			return corruptf("%s must be a JSON object, not null", what)
450		}
451		members, err := strictCircuitObject(raw, what)
452		if err != nil {
453			return err
454		}
455	
456		var out persistCircuit
457	
458		requireString := func(key string, dst *string) error {
459			r, err := storedRecordShape.require(members, key, what)
460			if err != nil {
461				return err
462			}
463			v, err := storedRecordShape.string(r, what+" field "+strconv.Quote(key))
464			if err != nil {
465				return err
466			}
467			*dst = v
468			return nil
469		}
470		requireInt := func(key string, dst *int) error {
471			r, err := storedRecordShape.require(members, key, what)
472			if err != nil {
473				return err
474			}
475			v, err := storedRecordShape.int(r, what+" field "+strconv.Quote(key))
476			if err != nil {
477				return err
478			}
479			*dst = v
480			return nil
481		}
482	
483		if err := requireString("name", &out.Name); err != nil {
484			return err
485		}
486		if err := requireInt("version", &out.Version); err != nil {
487			return err
488		}
489		if err := requireInt("constraints", &out.Constraints); err != nil {
490			return err
491		}
492		if err := requireInt("public_inputs", &out.PublicInputs); err != nil {
493			return err
494		}
495		if err := requireInt("private_inputs", &out.PrivateInputs); err != nil {
496			return err
497		}
498		frozenRaw, err := storedRecordShape.require(members, "frozen", what)
499		if err != nil {
500			return err
501		}
502		out.Frozen, err = storedRecordShape.bool(frozenRaw, what+" field "+strconv.Quote("frozen"))
503		if err != nil {
504			return err
505		}
506		if err := requireString("description", &out.Description); err != nil {
507			return err
508		}
509	
510		// definition is the only optional member: absent or null both mean the
511		// counts-only legacy state.
512		if defRaw, present := members["definition"]; present {
513			if string(bytes.TrimSpace(defRaw)) != "null" {
514				var def persistDefinition
515				if err := json.Unmarshal(defRaw, &def); err != nil {
516					var se StoreError
517					if errors.As(err, &se) {
518						return err // already reported as data corruption
519					}
520					return corruptf("%s field %s is not a valid constraint definition: %v", what, strconv.Quote("definition"), err)
521				}
522				out.Definition = &def
523			}
524		}
525	
526		*c = out
527		return nil
528	}
