530	// strictCircuitObject decodes one committed circuit record's own member map,
531	// demanding a JSON object with exactly the known top-level fields once.
532	func strictCircuitObject(raw []byte, what string) (map[string]json.RawMessage, error) {
533		return strictObjectMembers(raw, what, persistCircuitFields)
534	}
535	
536	// strictObjectMembers decodes one committed record's own member map,
537	// demanding a JSON object without repeated keys. A non-nil allowed list
538	// restricts which keys may appear; nil allows any key. It scans only the
539	// record's own level: the envelope scanner already attributes a duplicated
540	// top-level key to this record, and nested values such as the constraint
541	// definition own their (more precise) strict decoders. Keys are compared
542	// after JSON unescaping, so a field repeated through a \uXXXX spelling is
543	// still a duplicate, even when both values are identical.
544	func strictObjectMembers(raw []byte, what string, allowedFields []string) (map[string]json.RawMessage, error) {
545		trimmed := bytes.TrimSpace(raw)
546		if len(trimmed) == 0 || trimmed[0] != '{' {
547			return nil, corruptf("%s must be a JSON object", what)
548		}
549		dec := json.NewDecoder(bytes.NewReader(trimmed))
550		dec.UseNumber()
551		open, err := dec.Token()
552		if err != nil || open != json.Delim('{') {
553			return nil, corruptf("%s must be a JSON object", what)
554		}
555		var allowed map[string]bool
556		if allowedFields != nil {
557			allowed = make(map[string]bool, len(allowedFields))
558			for _, f := range allowedFields {
559				allowed[f] = true
560			}
561		}
562		members := make(map[string]json.RawMessage)
563		for dec.More() {
564			keyTok, err := dec.Token()
565			if err != nil {
566				return nil, corruptf("%s is not valid JSON: %v", what, err)
567			}
568			key, ok := keyTok.(string)
569			if !ok {
570				return nil, corruptf("%s is not valid JSON", what)
571			}
572			if allowed != nil && !allowed[key] {
573				return nil, corruptf("%s has unknown field %q", what, key)
574			}
575			if _, repeated := members[key]; repeated {
576				return nil, corruptf("%s contains duplicate field %q", what, key)
577			}
578			var value json.RawMessage
579			if err := dec.Decode(&value); err != nil {
580				return nil, corruptf("%s is not valid JSON: %v", what, err)
581			}
582			members[key] = value
583		}
584		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
585			return nil, corruptf("%s is not valid JSON", what)
586		}
587		if _, err := dec.Token(); err != io.EOF {
588			return nil, corruptf("%s is not valid JSON: trailing data after the object", what)
589		}
590		return members, nil
591	}
