593	type persistSetup struct {
594		Name    string `json:"name"`
595		Version int    `json:"version"`
596	}
597	
598	type persistJob struct {
599		ID       string `json:"id"`
600		Circuit  string `json:"circuit"`
601		Version  int    `json:"version"`
602		Kind     string `json:"kind"`
603		Attempt  int    `json:"attempt"`
604		Artifact string `json:"artifact,omitempty"`
605		// CompiledHash is the optional binding to the pinned version's compiled
606		// artifact, stored exactly as submitted.
607		CompiledHash string `json:"compiled_hash,omitempty"`
608	}
609	
610	// compiledHashKey is the canonical spelling of a job record's
611	// compiled-artifact binding field.
612	const compiledHashKey = "compiled_hash"
613	
614	// isCompiledHashKey reports whether key is an accepted spelling of the
615	// compiled-artifact binding field: only "compiled_hash" itself and ASCII
616	// letter-case variants such as "COMPILED_HASH" or "CoMpIlEd_HaSh". Keys are
617	// already JSON-unescaped at this point, so an escaped spelling of any of
618	// these forms lands here too. Non-ASCII letters are never folded here.
619	func isCompiledHashKey(key string) bool {
620		if len(key) != len(compiledHashKey) {
621			return false
622		}
623		for i := 0; i < len(key); i++ {
624			c := key[i]
625			if c >= 'A' && c <= 'Z' {
626				c += 'a' - 'A'
627			}
628			if c != compiledHashKey[i] {
629				return false
630			}
631		}
632		return true
633	}
634	
635	// compiledHashLookalike reports a member key encoding/json would match onto
636	// the binding field's struct tag yet which is not an accepted ASCII spelling
637	// (isCompiledHashKey). Struct-tag matching in encoding/json folds with the
638	// Unicode simple case-folding rules (bytes.EqualFold), so a non-ASCII
639	// lookalike — "compiled_haſh" with U+017F long s, whether written directly
640	// or as the JSON escape u017f — silently fills CompiledHash and would let a
641	// damaged binding (null above all) read as unbound, then vanish on the next
642	// commit. Such a key is damage, regardless of its value or of a correctly
643	// spelled sibling key being present. Several aliases are reported in
644	// lexicographic order so the message is stable.
645	func compiledHashLookalike(members map[string]json.RawMessage) string {
646		var aliases []string
647		for key := range members {
648			if isCompiledHashKey(key) {
649				continue
650			}
651			if strings.EqualFold(key, compiledHashKey) {
652				aliases = append(aliases, key)
653			}
654		}
655		if len(aliases) == 0 {
656			return ""
657		}
658		sort.Strings(aliases)
659		return aliases[0]
660	}
661	
662	// Strict decoding of the compiled-artifact binding on a committed job record.
663	//
664	// compiled_hash is a field whose presence is meaningful: records written
665	// before bindings existed simply omit it, and an explicit "" is the unbound
666	// state. But once the key appears its value must be a JSON string. A null is
667	// not "no binding" — it is damage to a binding the record claims to carry,
668	// and so is a number, boolean, array or object in its place. Reading either
669	// as the zero string would silently turn a bound job into an unbound one
670	// (and the next commit would drop the field entirely), so the read is
671	// refused as data corruption instead. A repeated key — including one
672	// repeated through JSON string escapes, even with identical values — is
673	// likewise refused rather than resolved to its last value. A legal non-empty
674	// string keeps being matched against the pinned version's artifact by
675	// validateEnvelope, exactly as written.
676	//
677	// The field is recognized under any ASCII letter-case spelling, so a record
678	// carrying "COMPILED_HASH" (or any mixed-case form, escaped or not) is the
679	// same binding and follows the same rules: a single such key is read with
680	// the full string validation above, and two spellings of the field on one
681	// record — even with byte-identical values — are a duplicate binding and
682	// corrupt the read rather than being resolved by key order.
683	//
684	// Non-ASCII spellings are not accepted even though encoding/json itself
685	// would fold them onto the field: its struct-tag matching uses Unicode case
686	// folding, under which "compiled_haſh" (U+017F long s, written directly or
687	// as the JSON escape u017f) names CompiledHash just like "compiled_hash".
688	// Such a lookalike is damage to the binding the record claims to carry and
689	// is refused whatever its value — null, a legal hash or an explicit "" —
690	// and even when a correctly spelled "compiled_hash" sits beside it, in
691	// either key order and whether the two values agree. The damaged binding
692	// must never read as an unbound job and disappear on the next commit.
693	//
694	// Only the binding field is judged here; every other field keeps the
695	// ordinary struct decoding.
696	func (j *persistJob) UnmarshalJSON(raw []byte) error {
697		const what = "stored job record"
698		if string(bytes.TrimSpace(raw)) == "null" {
699			return corruptf("%s must be a JSON object, not null", what)
700		}
701		members, err := strictObjectMembers(raw, what, nil)
702		if err != nil {
703			return err
704		}
705		// Name the job in a binding-field failure when its id is legible; the id
706		// itself is decoded for real by the ordinary pass below.
707		where := what
708		if idRaw, ok := members["id"]; ok {
709			if id, idErr := storedRecordShape.string(idRaw, what+` field "id"`); idErr == nil {
710				where = fmt.Sprintf("stored job record %q", id)
711			}
712		}
713		// Reject a non-ASCII spelling that encoding/json's Unicode-folded tag
714		// matching would silently read as this field ("compiled_haſh" with long
715		// s, directly written or ſ-escaped), whatever its value and whether
716		// or not a correctly spelled key accompanies it. It must never be ignored
717		// as an unknown member, which would let a damaged binding read unbound.
718		if alias := compiledHashLookalike(members); alias != "" {
719			return corruptf("%s carries the binding field %q under non-ASCII spelling %q; such a lookalike spelling is data corruption",
720				where, compiledHashKey, alias)
721		}
722		// Every accepted spelling of the binding field counts as the same one
723		// field; the record may carry it at most once, however it is capitalized.
724		var bindingKeys []string
725		for key := range members {
726			if isCompiledHashKey(key) {
727				bindingKeys = append(bindingKeys, key)
728			}
729		}
730		if len(bindingKeys) > 1 {
731			sort.Strings(bindingKeys)
732			quoted := make([]string, len(bindingKeys))
733			for i, k := range bindingKeys {
734				quoted[i] = strconv.Quote(k)
735			}
736			return corruptf("%s carries the binding field %q more than once (as %s)",
737				where, compiledHashKey, strings.Join(quoted, ", "))
738		}
739		compiledHash := ""
740		hasBinding := false
741		if len(bindingKeys) == 1 {
742			hash, err := storedRecordShape.string(members[bindingKeys[0]], where+` field "compiled_hash"`)
743			if err != nil {
744				return err
745			}
746			compiledHash, hasBinding = hash, true
747		}
748		type plainJob persistJob
749		var decoded plainJob
750		if err := json.Unmarshal(raw, &decoded); err != nil {
751			return corruptf("%s is not valid JSON: %v", what, err)
752		}
753		if hasBinding {
754			decoded.CompiledHash = compiledHash
755		}
756		*j = persistJob(decoded)
757		return nil
758	}
