// jsonShape is the strict-JSON rule set the definition schema is built from:
// objects name only allowed keys, required members are present, scalars have
// their declared JSON type and no object repeats a key. The fail constructor
// tags each rejection with the reading path's error kind; nullSuffix is
// appended to object/array null rejections so the committed-data path can
// name null explicitly where the import grammar simply rejects the shape.
type jsonShape struct {
	fail       func(format string, args ...any) error
	nullSuffix string
}

// object decodes raw as the single JSON object at this level and returns its
// raw members. It checks this one object's own level only: syntax, a single
// trailing-value-free object, unknown keys and repeated keys. Nested values
// are captured unparsed and handed to their own decoders — a constraint
// object inside "constraints", a term object inside an a/b/c side — which is
// where their own level gets checked, exactly once. The decoder descends into
// a nested value only to skip it while reading the enclosing object, so an
// object is never structurally interpreted at an outer level, again at its
// constraint and again at its term.
func (s jsonShape) object(raw []byte, allowed []string, what string) (map[string]json.RawMessage, error) {
	trimmed := bytes.TrimSpace(raw)
	if string(trimmed) == "null" {
		return nil, s.fail("%s must be a JSON object%s", what, s.nullSuffix)
	}
	dec := json.NewDecoder(bytes.NewReader(trimmed))
	dec.UseNumber()
	open, err := dec.Token()
	if err != nil || open != json.Delim('{') {
		// Covers the empty document, arrays, scalars and malformed JSON.
		return nil, s.fail("%s must be a JSON object", what)
	}
	allowedSet := make(map[string]bool, len(allowed))
	for _, k := range allowed {
		allowedSet[k] = true
	}
	members := make(map[string]json.RawMessage)
	for dec.More() {
		keyTok, err := dec.Token()
		if err != nil {
			return nil, s.fail("%s is not valid JSON: %v", what, err)
		}
		key, ok := keyTok.(string)
		if !ok {
			return nil, s.fail("%s is not valid JSON", what)
		}
		if !allowedSet[key] {
			return nil, s.fail("%s has unknown field %q", what, key)
		}
		// json.Token returns an object key after JSON unescaping, so a key
		// repeated through a \uXXXX spelling is still a duplicate, even when
		// both values are identical. encoding/json would otherwise keep the
		// last value silently.
		if _, repeated := members[key]; repeated {
			return nil, s.fail("%s contains duplicate field %q", what, key)
		}
		// Capture the value raw without interpreting its contents: the member
		// is checked structurally by the decoder that owns its own level.
		var value json.RawMessage
		if err := dec.Decode(&value); err != nil {
			return nil, s.fail("%s is not valid JSON: %v", what, err)
		}
		members[key] = value
	}
	if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
		return nil, s.fail("%s is not valid JSON", what)
	}
	// Reject trailing tokens after the one object.
	if _, err := dec.Token(); err != io.EOF {
		return nil, s.fail("%s is not valid JSON: trailing data after the object", what)
	}
	return members, nil
}

